const all = $input.all().map(item => item.json);
const systemsWeekly = $('Sunday 09:00 Systems Review').isExecuted;
const now = $now.setZone('Europe/Copenhagen');
const weekStart = now.startOf('week').minus({ weeks: 1 }).toISODate();
const weekEnd = now.startOf('week').minus({ days: 1 }).toISODate();

if (systemsWeekly) {
  const automations = all.filter(e => String(e.entity_id || '').startsWith('automation.'))
    .map(e => ({entity_id:e.entity_id,name:e.attributes?.friendly_name||e.entity_id,state:e.state,last_changed:e.last_changed}));
  const unavailableAll = all.filter(e => ['unavailable','unknown'].includes(String(e.state||'').toLowerCase()));
  const unavailable = unavailableAll.slice(0,40).map(e => ({entity_id:e.entity_id,state:e.state,name:e.attributes?.friendly_name||e.entity_id}));
  const relevant = all.filter(e => {
    const id=String(e.entity_id||'');
    const name=String(e.attributes?.friendly_name||'');
    return /staircase_battery|stromligning|home.?core|home.?spark|spark|core|model|performance|error|health|uptime|backup|update|cpu|gpu|memory|temperature/i.test(id+' '+name);
  }).slice(0,100).map(e => ({entity_id:e.entity_id,name:e.attributes?.friendly_name||e.entity_id,state:e.state,last_updated:e.last_updated,installed_version:e.attributes?.installed_version,latest_version:e.attributes?.latest_version,unit_of_measurement:e.attributes?.unit_of_measurement,device_class:e.attributes?.device_class}));
  const hostEntities=relevant.filter(e=>/home.?core|home.?spark|spark|core/i.test(e.entity_id+' '+e.name));
  const updateEntities=relevant.filter(e=>String(e.entity_id).startsWith('update.')||e.latest_version);
  const attentionAutomations=automations.filter(e=>['unavailable','unknown'].includes(String(e.state).toLowerCase()));
  const snapshot={captured_at:now.toISO(),review_period:'Week '+weekStart+' through '+weekEnd,home_assistant:{total_entities:all.length,automations_total:automations.length,automations_unavailable_or_unknown:attentionAutomations,unavailable_or_unknown_entity_count:unavailableAll.length,unavailable_or_unknown_entities:unavailable,relevant_states:relevant},home_core_and_spark_coverage:{matching_entity_count:hostEntities.length,matching_entities:hostEntities,note:hostEntities.length?'HA has matching host telemetry; use only values present above.':'No Home-core or Home-spark telemetry entities were exposed through Home Assistant in this run.'},model_and_software_updates:updateEntities};
  const title='HomeCompute weekly systems review — '+weekStart+' to '+weekEnd;
  const prompt=[
    'Prepare the weekly HomeCompute systems review for '+weekStart+' through '+weekEnd+'. Snapshot: '+JSON.stringify(snapshot),
    'Verify evidence across Home Assistant, home-core, and home-spark. Separate observed facts from missing coverage. Do not infer a host is healthy when its telemetry is absent.',
    'Review battery and energy states, automation availability, error or unavailable signals, model/software update signals, and any performance/resource metrics present. “off” is a normal automation state; do not report it as an error. This snapshot has current states, not historical automation success logs.',
    'Use web search to identify at most two relevant new model/runtime/Home Assistant ideas from the allowed primary sources. Include source links and why they may fit this setup. Treat upstream claims as candidates only; do not claim they outperform current models without local benchmark evidence.',
    'Return the dated heading and at most five concise bullets: findings, reliability/errors, performance, model/update signals, and one prioritized improvement idea. State clearly when core/Spark metrics or historical trends are not available. Never recommend control, deployment, or model-promotion changes as automatic actions.'
  ].join('\n');
  return [{json:{reportType:'system_weekly',period:'Week '+weekStart+' through '+weekEnd,notificationTitle:title,prompt}}];
}

const relevant=all.filter(e=>/staircase_battery|stromligning_current_price_vat|stromligning_tomorrow_available_vat/i.test(String(e.entity_id||'')));
const byId={}; for (const e of relevant) byId[e.entity_id]=e;
const weekly=true;
const period='Completed week '+weekStart+' through '+weekEnd;
const reportType='weekly';
const priceEntities=[byId['sensor.stromligning_current_price_vat'],byId['binary_sensor.stromligning_tomorrow_available_vat']].filter(Boolean);
const priceDays={};
for (const e of priceEntities) for (const s of (Array.isArray(e.attributes?.prices)?e.attributes.prices:[])) {
 const day=String(s.start||'').slice(0,10); if(!day||!Number.isFinite(Number(s.price))) continue;
 if(!priceDays[day]) priceDays[day]=[]; priceDays[day].push({start:s.start,price_dkk_per_kwh:Number(s.price)});
}
const priceSummary=Object.entries(priceDays).map(([date,slots])=>{const sorted=[...slots].sort((a,b)=>a.price_dkk_per_kwh-b.price_dkk_per_kwh);const values=slots.map(s=>s.price_dkk_per_kwh);return {date,slot_count:slots.length,min:Math.min(...values),max:Math.max(...values),mean:values.reduce((a,b)=>a+b,0)/values.length,cheapest:sorted.slice(0,3),most_expensive:sorted.slice(-3).reverse()};});
const planEntity=byId['sensor.staircase_battery_operation_plan'];
const plan=planEntity?.attributes||{};
const rawBlocks=Array.isArray(plan.blocks)?plan.blocks:[];
const grouped=[];
for (const b of rawBlocks) {const prior=grouped[grouped.length-1];const gap=prior&&b.start&&prior.end?Math.abs(new Date(b.start)-new Date(prior.end)):999999;
 if(!prior||prior.action!==b.action||gap>60000) grouped.push({start:b.start,end:b.end,action:b.action,soc_start:b.soc_start??b.soc,soc_end:b.soc_end??b.soc,energy_kwh:Number(b.energy_kwh||0),expected_load_kwh:Number(b.expected_load_kwh||0),expected_grid_import_kwh:Number(b.expected_grid_import_kwh||0),expected_cost_dkk:Number(b.expected_cost_dkk||0),expected_savings_dkk:Number(b.expected_savings_dkk||0),reasons:b.reason?[b.reason]:[]});
 else {prior.end=b.end;prior.soc_end=b.soc_end??b.soc??prior.soc_end;prior.energy_kwh+=Number(b.energy_kwh||0);prior.expected_load_kwh+=Number(b.expected_load_kwh||0);prior.expected_grid_import_kwh+=Number(b.expected_grid_import_kwh||0);prior.expected_cost_dkk+=Number(b.expected_cost_dkk||0);prior.expected_savings_dkk+=Number(b.expected_savings_dkk||0);if(b.reason&&!prior.reasons.includes(b.reason))prior.reasons.push(b.reason);}
}
const omit=new Set(['prices','blocks','friendly_name','icon','options','min','max','step','mode','editable']);
const clean=value=>{if(Array.isArray(value))return value.length>40?{item_count:value.length,first_items:value.slice(0,3),last_items:value.slice(-3)}:value;if(!value||typeof value!=='object')return value;const out={};for(const [k,v] of Object.entries(value))if(!omit.has(k))out[k]=clean(v);return out;};
const entities=relevant.filter(e=>!priceEntities.includes(e)&&e.entity_id!=='sensor.staircase_battery_operation_plan').map(e=>({entity_id:e.entity_id,state:e.state,last_updated:e.last_updated,attributes:clean(e.attributes||{})}));
const planSummary=planEntity?{entity_id:planEntity.entity_id,state:planEntity.state,last_updated:planEntity.last_updated,attributes:clean(Object.fromEntries(Object.entries(plan).filter(([k])=>k!=='blocks'))),block_count:rawBlocks.length,blocks:grouped}:null;
const tomorrow=byId['binary_sensor.stromligning_tomorrow_available_vat'];
const snapshot={captured_at:now.toISO(),review_period:period,report_type:reportType,price_days:priceSummary,tomorrow_price_availability:tomorrow?{state:tomorrow.state,attributes:clean(Object.fromEntries(Object.entries(tomorrow.attributes||{}).filter(([k])=>k!=='prices')))}:null,plan:planSummary,entities};
const title='Battery plan weekly review — '+weekStart+' to '+weekEnd;
const id='battery_plan_week_'+weekStart;
const prompt=['Review '+period+'. Type: '+reportType+'. Snapshot: '+JSON.stringify(snapshot),'Daily: use dated actuals only for yesterday. Separately summarize today’s plan: modeled cost vs baseline and savings, SOC range and key charge/discharge window(s). Give compact price range and cheapest/peak times for each available plan date, plus tomorrow-price availability.','Weekly: give available last-week savings, charge, discharge and cycle totals (label estimates), plus dated plan/execution coverage out of 7 days. Do not reconstruct missing days.','No CT meter means grid import/export and bill impact are unknown, not zero. Qualify estimated totals and mention pre-1.5.4 telemetry only when relevant. Mention optimizer/execution/forecast only if abnormal or limiting.','Output max 650 characters: dated heading and at most 3 short bullets. Lead with result. Omit normal status, missing-detail inventories, long explanations, repeated caveats, full entity lists and follow-up. Label modeled/estimated values. Never recommend battery control changes.'].join('\n');
return [{json:{reportType,period,notificationTitle:title,notificationId:id,prompt,snapshotCharacters:JSON.stringify(snapshot).length}}];

const v=$input.first()?.json||{};
const candidates=[v.output_text,v.output,v.text,v.response,v.content,v.message?.content,v.output?.[0]?.content?.[0]?.text,v.output?.[0]?.text];
const report=candidates.find(x=>typeof x==='string'&&x.trim());
if(!report) throw new Error('OpenAI returned no report text; Telegram delivery stopped.');
return [{json:{report:report.trim()}}];
